const out=[];const fr=figma.currentPage.children.filter(n=>n.type==='FRAME').sort((a,b)=>a.name<b.name?-1:1);
for(const f of fr){out.push(`## ${f.name} ${f.id} @${f.x},${f.y} ${f.width}x${f.height}`);
 const kids=f.children.map(c=>`${c.name}[y${Math.round(c.y)} h${Math.round(c.height)}]`).join(' ');out.push(kids);
 const fy=f.absoluteTransform[1][2],fx=f.absoluteTransform[0][2];
 f.findAll(n=>n.visible&&(n.name==='Content'||n.name==='Spacer'||n.name==='Image'||n.type==='TEXT')).forEach(n=>{
  let vis=true,p=n;while(p&&p!==f){if(!p.visible)vis=false;p=p.parent}if(!vis)return;
  const y=Math.round(n.absoluteTransform[1][2]-fy),x=Math.round(n.absoluteTransform[0][2]-fx);
  if(n.name==='Content'){const b=Math.max(...n.children.filter(c=>c.visible).map(c=>c.y+c.height));out.push(` Content y${y} h${Math.round(n.height)} innerBottom ${Math.round(b)}`)}
  else if(n.name==='Spacer')out.push(` Spacer y${y} h${Math.round(n.height)}`);
  else if(n.name==='Image')out.push(` Image x${x} y${y} ${Math.round(n.width)}x${Math.round(n.height)} ${n.mainComponent&&n.mainComponent.name}`);
  else if(n.height>26&&n.parent.type!=='INSTANCE'||n.height>30)out.push(` T x${x} y${y} ${Math.round(n.width)}x${Math.round(n.height)} ${n.characters.slice(0,28)}`);
 });
}
return out.join('\n');

